// Organic visual treatment of the demo orchestration state; no AI service is connected.
let organismPointer={x:0,y:0},organismTarget={x:0,y:0},organismExcitation=0,organismLast=0;
const organicCaption=document.createElement('div');organicCaption.className='organic-caption';organicCaption.textContent='SENSING · CONNECTING · PROTECTING';$('.core-stage').append(organicCaption);
$('.core-stage').addEventListener('pointermove',e=>{if(reducedMotion.matches||motionPaused)return;const b=e.currentTarget.getBoundingClientRect();organismTarget={x:(e.clientX-b.left-b.width/2)/b.width,y:(e.clientY-b.top-b.height/2)/b.height}});
$('.core-stage').addEventListener('pointerleave',()=>organismTarget={x:0,y:0});
function exciteCore(kind){organismExcitation=1;coreDeck.classList.add('reacting');$('.core-center').dataset.response=kind;organicCaption.textContent=kind==='scan'?'SCANNING · MAPPING YOUR FLEET':'PATCH ROLLOUT · SIGNAL SENT';setTimeout(()=>{coreDeck.classList.remove('reacting');organicCaption.textContent='SENSING · CONNECTING · PROTECTING';$('.core-center').dataset.response=''},2200)}
$('#scan').addEventListener('click',()=>exciteCore('scan'));const organicDeploy=deploy;deploy=function(ids){const result=organicDeploy(ids);if(result.started.length)exciteCore('deploy');return result};
function organicPath(x,y,r,t,layer=0){ctx.beginPath();for(let i=0;i<=180;i++){const a=i/180*Math.PI*2;const drift=Math.sin(a*3+t*.65+layer*.16)*.052+Math.cos(a*5-t*.4+layer*.3)*.027+Math.sin(a*2+t*.25)*.035;const rr=r*(1+drift);const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr*.92;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath()}
drawCore=function(){if(!cw||!ch)return;ctx.clearRect(0,0,cw,ch);const t=coreTime,step=Math.max(0,t-organismLast);organismLast=t;organismPointer.x+=(organismTarget.x-organismPointer.x)*.035;organismPointer.y+=(organismTarget.y-organismPointer.y)*.035;organismExcitation=Math.max(0,organismExcitation-step*.5);const x=cw*.5+organismPointer.x*15,y=ch*.48+organismPointer.y*12,r=Math.min(cw*.245,ch*.335),breath=1+Math.sin(t*.85)*.025;const energy=organismExcitation;const aura=ctx.createRadialGradient(x,y,r*.15,x,y,r*1.6);aura.addColorStop(0,'#c9f8a927');aura.addColorStop(.5,'#90c38918');aura.addColorStop(1,'#87b59200');ctx.fillStyle=aura;ctx.fillRect(0,0,cw,ch);
// Fine membranes form a continuously deforming volume, rather than rigid rings.
for(let j=24;j>=0;j--){const rr=r*(.62+j*.014)*breath;organicPath(x,y,rr,t,j);ctx.strokeStyle=`rgba(${170+j*2},${210+j},${143+j*2},${j%4===0?.2:.065})`;ctx.lineWidth=j%4===0?1:.65;ctx.stroke()}
// A translucent central surface keeps the name legible over the neural field.
organicPath(x,y,r*.67*breath,t,4);const surface=ctx.createRadialGradient(x-r*.25,y-r*.4,0,x,y,r*.75);surface.addColorStop(0,'#557151bb');surface.addColorStop(.48,'#294d3cc7');surface.addColorStop(1,'#183b32df');ctx.fillStyle=surface;ctx.fill();ctx.strokeStyle='#d3f2ae57';ctx.lineWidth=1.1;ctx.stroke();
// Flowing longitudinal strands with traveling synapses.
for(let k=0;k<22;k++){const phi=k/22*Math.PI*2+t*.085;const front=Math.cos(phi);ctx.beginPath();for(let j=0;j<=60;j++){const a=j/60*Math.PI;const mod=1+Math.sin(a*5+t*.8+k*.3)*.035;const px=x+Math.sin(a)*Math.cos(phi+Math.sin(a*2+t*.3)*.15)*r*mod;const py=y+Math.cos(a)*r*.96*breath;if(Math.hypot(px-x,py-y)<r*.69&&front<.25){ctx.moveTo(px,py);continue}j?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.strokeStyle=`rgba(184,226,165,${front>.25?.13:.055})`;ctx.lineWidth=.65;ctx.stroke();const a=((t*.13+k*.071)%1)*Math.PI;const px=x+Math.sin(a)*Math.cos(phi+Math.sin(a*2+t*.3)*.15)*r;const py=y+Math.cos(a)*r*.96*breath;if(Math.hypot(px-x,py-y)>r*.7){ctx.beginPath();ctx.arc(px,py,front>0?1.6:1,0,Math.PI*2);ctx.fillStyle=front>0?'#e0f8beaa':'#b0d8a45c';ctx.fill()}}
// Branching connections carry signals to the actual interactive asset nodes.
coreDeck.querySelectorAll('.core-node').forEach((node,i)=>{const b=node.getBoundingClientRect(),stage=canvas.getBoundingClientRect();const nx=b.left-stage.left+b.width/2,ny=b.top-stage.top+b.height/2;const angle=Math.atan2(ny-y,nx-x),sx=x+Math.cos(angle)*r*.98,sy=y+Math.sin(angle)*r*.96;const bend=Math.sin(t*.4+i)*12;const mx=(sx+nx)/2+Math.cos(angle+Math.PI/2)*bend,my=(sy+ny)/2+Math.sin(angle+Math.PI/2)*bend;const critical=node.classList.contains('risk');for(let branch=0;branch<3;branch++){ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(mx+branch*4,my-branch*5,nx,ny);ctx.strokeStyle=critical?'#dd9aa52c':'#c7edb132';ctx.lineWidth=.7;ctx.stroke()}for(let p=0;p<3;p++){const f=(t*(.12+energy*.2)+i*.17+p/3)%1,px=(1-f)*(1-f)*sx+2*(1-f)*f*mx+f*f*nx,py=(1-f)*(1-f)*sy+2*(1-f)*f*my+f*f*ny;ctx.beginPath();ctx.arc(px,py,1.6+energy,0,Math.PI*2);ctx.fillStyle=critical?'#f2acb8':'#d9f7b7';ctx.fill()}});
// Peripheral motes follow a slow organic current, never crossing data controls.
for(let i=0;i<58;i++){const a=i*2.39996+t*(i%2?.035:-.025),rr=r*(1.08+(i%11)*.025+Math.sin(t*.3+i)*.025);ctx.beginPath();ctx.arc(x+Math.cos(a)*rr,y+Math.sin(a)*rr*.96,i%7===0?1.5:.65,0,Math.PI*2);ctx.fillStyle=i%7===0?'#daf0b794':'#accb9760';ctx.fill()}
if(energy>0){for(let i=0;i<3;i++){organicPath(x,y,r*(1+(1-energy)*.6+i*.09),t,i);ctx.strokeStyle=`rgba(220,246,166,${energy*.2})`;ctx.lineWidth=1;ctx.stroke()}}};
drawCore();
